create table if not exists public.ls_groups(id uuid primary key default gen_random_uuid(), name text not null, owner uuid not null references auth.users(id) on delete cascade);
create table if not exists public.ls_group_members(group_id uuid references public.ls_groups(id) on delete cascade, member uuid references auth.users(id) on delete cascade, primary key(group_id,member));
create table if not exists public.ls_group_messages(id bigint generated always as identity primary key, group_id uuid references public.ls_groups(id) on delete cascade, sender uuid references auth.users(id) on delete cascade, body text not null, material jsonb);
alter table public.ls_groups enable row level security;
alter table public.ls_group_members enable row level security;
alter table public.ls_group_messages enable row level security;
revoke all on public.ls_groups,public.ls_group_members,public.ls_group_messages from anon,authenticated;
create or replace function public.ls_group_create(title text, peers uuid[]) returns uuid language plpgsql security definer set search_path='' as $$ declare gid uuid; p uuid; begin if auth.uid() is null or length(trim(title)) not between 1 and 80 then raise exception 'Ungültige Gruppe'; end if; insert into public.ls_groups(name,owner) values(trim(title),auth.uid()) returning id into gid; insert into public.ls_group_members values(gid,auth.uid()); foreach p in array peers loop if not exists(select 1 from public.ls_connections c where c.accepted and ((c.sender=auth.uid() and c.recipient=p) or(c.recipient=auth.uid() and c.sender=p))) then raise exception 'Keine Freundschaft'; end if; insert into public.ls_group_members values(gid,p) on conflict do nothing; end loop; return gid; end $$;
create or replace function public.ls_group_list() returns table(id uuid,name text) language sql security definer set search_path='' as $$ select g.id,g.name from public.ls_groups g join public.ls_group_members m on m.group_id=g.id where m.member=auth.uid() $$;
create or replace function public.ls_group_chat(gid uuid) returns table(sender uuid,body text,material jsonb) language sql security definer set search_path='' as $$ select m.sender,m.body,m.material from public.ls_group_messages m where m.group_id=gid and exists(select 1 from public.ls_group_members x where x.group_id=gid and x.member=auth.uid()) order by m.id $$;
create or replace function public.ls_group_send(gid uuid,body text,material jsonb) returns void language plpgsql security definer set search_path='' as $$ begin if not exists(select 1 from public.ls_group_members x where x.group_id=gid and x.member=auth.uid()) then raise exception 'Kein Zugriff'; end if; if length(body)>10000 or pg_column_size(material)>4000000 then raise exception 'Nachricht zu groß'; end if; insert into public.ls_group_messages(group_id,sender,body,material) values(gid,auth.uid(),body,material); end $$;
revoke execute on function public.ls_group_create(text,uuid[]),public.ls_group_list(),public.ls_group_chat(uuid),public.ls_group_send(uuid,text,jsonb) from public,anon;
grant execute on function public.ls_group_create(text,uuid[]),public.ls_group_list(),public.ls_group_chat(uuid),public.ls_group_send(uuid,text,jsonb) to authenticated;
notify pgrst,'reload schema';
